16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	import org.springframework.samples.petclinic.util.BusinessDay;
20	
21	import jakarta.persistence.*;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 format")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "registration_date")
56	    private LocalDate registrationDate;
57	
58	    @Column(name = "customer_code")
59	    private String customerCode;
60	
61	    public String getCustomerCode() {
62	        return this.customerCode;
63	    }
64	
65	    public void setCustomerCode(String customerCode) {
66	        this.customerCode = customerCode;
67	    }
68	
69	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
70	    private Set<Pet> pets;
71	
72	    public LocalDate getRegistrationDate() {
73	        return this.registrationDate;
74	    }
75	
76	    /** Set the registration date, defaulting to the server's current date when none is supplied. */
77	    public void setRegistrationDate(LocalDate registrationDate) {
78	        this.registrationDate = BusinessDay.onOrNextBusinessDay(
79	            registrationDate == null ? LocalDate.now() : registrationDate);
80	    }
81	
82	    public String getEmail() {
83	        return this.email;
84	    }
85	
86	    public void setEmail(String email) {
87	        this.email = email == null ? null : email.toLowerCase();
88	    }
89	
90	    public String getAddress() {
91	        return this.address;
92	    }
93	
94	    public void setAddress(String address) {
95	        this.address = address;
96	    }
97	
98	    public String getCity() {
99	        return this.city;
100	    }
101	
102	    public void setCity(String city) {
103	        this.city = city;
104	    }
105	
106	    public String getTelephone() {
107	        return this.telephone;
108	    }
109	
110	    public void setTelephone(String telephone) {
111	        this.telephone = telephone;
112	    }
113	
114	    protected Set<Pet> getPetsInternal() {
115	        if (this.pets == null) {
116	            this.pets = new HashSet<>();
117	        }
118	        return this.pets;
119	    }
120	
121	    protected void setPetsInternal(Set<Pet> pets) {
122	        this.pets = pets;
123	    }
124	
125	    public List<Pet> getPets() {
126	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
127	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
128	        return Collections.unmodifiableList(sortedPets);
129	    }
130	
131	    public void setPets(List<Pet> pets) {
132	        this.pets = new HashSet<>(pets);
133	    }
134	
135	    public void addPet(Pet pet) {
136	        getPetsInternal().add(pet);
137	        pet.setOwner(this);
138	    }
139	
140	    /**
141	     * Return the Pet with the given name, or null if none found for this Owner.
142	     *
143	     * @param name to test
144	     * @return true if pet name is already in use
145	     */
146	    public Pet getPet(String name) {
147	        return getPet(name, false);
148	    }
149	
150	    /**
151	     * Return the Pet with the given name, or null if none found for this Owner.
152	     *
153	     * @param name to test
154	     * @return true if pet name is already in use
155	     */
156	    public Pet getPet(String name, boolean ignoreNew) {
157	        name = name.toLowerCase();
158	        for (Pet pet : getPetsInternal()) {
159	            if (!ignoreNew || !pet.isNew()) {
160	                String compName = pet.getName();
161	                compName = compName.toLowerCase();
162	                if (compName.equals(name)) {
163	                    return pet;
164	                }
165	            }
166	        }
167	        return null;
168	    }
169	
170	    public Pet getPet(Integer petId) {
171	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
172	    }
173	
174	    @Override
175	    public String toString() {
176	        return new ToStringCreator(this)
177	
178	            .append("id", this.getId())
179	            .append("new", this.isNew())
180	            .append("lastName", this.getLastName())
181	            .append("firstName", this.getFirstName())
182	            .append("address", this.address)
183	            .append("city", this.city)
184	            .append("telephone", this.telephone)
185	            .toString();
186	    }
187	}
